INSERT INTO `product` VALUES (1,'Baby Combo Set','Cute and comfy set for little girls! Comes with a black ‘Little Feminist’ t-shirt, soft dark shorts, pink shoes, blue hair tie, and sunglasses. Perfect for fun days out',4500.00,50,'BCS-001-234',3,'babies combo set.jpg','2026-05-25 09:20:00',NULL),(2,'Classic Black T-Shirt ','Soft and simple black t-shirt with a round neck perfect for everyday wear and easy to pair with any outfit.',2500.00,15,'CBT-002-023',1,'blackTshirt.jpg','2026-05-25 09:40:00',NULL),(3,'Blazer','Bold and statement ready, this black blazer features a unique diamond pattern filled with skulls, crowns, and emblems. Perfect for those who want to blend edgy style with formal flair. Great with a white shirt for sharp contrast.',5000.00,17,'BFM-003-232',1,'blazersformen.jpeg','2026-05-25 10:00:00',NULL),(4,'Kurta Set','Cream-colored kurta with matching pants and a colorful embroidered jacket perfect for special occasions and cultural celebrations. Stylish, comfortable, and full of charm.',8000.00,19,'KSB-083-393',3,'boykidsdress.jpg','2026-05-25 10:20:00',NULL),(5,'Black Tuxedo','This is a formal men\'s suit, typically worn for special occasions like weddings or black-tie events.',2500.00,9,'BTM-003-323',1,'blackcoat.webp','2026-05-25 10:40:00',NULL),(6,'Black Wedding Dress','Cassiee Custom Black Wedding Dress by Brides & Tailor, Custom Black Wedding Dress with sheer bodice, Custom Black V neck Dress',5000.00,10,'WDW-394-494',2,'blackdress.webp','2026-05-25 11:00:00',NULL),(7,'Gown','High Neck Ball Gown Black Sequin Wedding Dresses Long Sleeves Sweet 16 Dress',3000.00,15,'BGS-939-393',2,'blackgaun.webp','2026-05-25 11:20:00',NULL),(8,'Black Wedding Gown','Luxury Glitters Wedding Dresses Black Long Sleeves V Neck Tulle Bridal Gown.',6000.00,16,'BWG-983-903',2,'blackweddingdress.webp','2026-05-25 11:40:00',NULL),(9,'Cap','Inspired by a baseball cap, its design is both sleek and sophisticated.\r\nDesigned down to the last detail and made from high-quality